import assert from 'node:assert/strict';
import {page} from './page.mjs';

const items = ['first', 'second', 'third', 'fourth', 'fifth'];

assert.deepEqual(page(items, 2, 2), {
  rows: ['third', 'fourth'],
  total: 5,
});
assert.deepEqual(page(items, 3, 2), {rows: ['fifth'], total: 5});
assert.deepEqual(page(items, 4, 2), {rows: [], total: 5});
assert.deepEqual(page([], 1, 2), {rows: [], total: 0});

for (const invalid of [0, -1, 1.5, NaN, Infinity, '1', Number.MAX_SAFE_INTEGER + 1]) {
  assert.throws(() => page(items, invalid, 2), RangeError);
  assert.throws(() => page(items, 1, invalid), RangeError);
}

