import assert from 'node:assert/strict';

import { page } from './page.mjs';

const items = ['first', 'second', 'third', 'fourth', 'fifth'];

assert.deepEqual(page(items, 1, 2), {
  rows: ['first', 'second'],
  total: 5,
});
assert.deepEqual(page(items, 2, 2), {
  rows: ['third', 'fourth'],
  total: 5,
});
assert.deepEqual(page(items, 3, 2), {
  rows: ['fifth'],
  total: 5,
});
assert.deepEqual(page(items, 4, 2), { rows: [], total: 5 });
assert.deepEqual(page([], 1, 2), { rows: [], total: 0 });

const invalidValues = [
  0,
  -1,
  1.5,
  Number.NaN,
  Number.POSITIVE_INFINITY,
  Number.MAX_SAFE_INTEGER + 1,
  '1',
  null,
];

for (const invalidNumber of invalidValues) {
  assert.throws(() => page(items, invalidNumber, 2), RangeError);
}

for (const invalidSize of invalidValues) {
  assert.throws(() => page(items, 1, invalidSize), RangeError);
}

assert.deepEqual(page(items, Number.MAX_SAFE_INTEGER, 1), {
  rows: [],
  total: 5,
});
assert.deepEqual(page(items, 1, Number.MAX_SAFE_INTEGER), {
  rows: items,
  total: 5,
});

